/**
 * Unit tests for DeserializationContext#instantiationException.
 */
public class DeserializationContext_instantiationException_TriageGen2Test {

    @Mock
    private JsonParser _parser;

    @Mock
    private DeserializerFactory _deserializerFactory;

    private DeserializationContext _context;
    private TypeFactory _typeFactory;

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        _typeFactory = TypeFactory.defaultInstance();

        // DeserializationContext is abstract/protected, we use a concrete subclass or a mock.
        // Since we need to call the protected constructor, we mock the context or use a spy.
        // However, the method under test is public, but it uses internal fields like _parser.
        // We will use a subclass to allow instantiation for testing.
        _context = new TestDeserializationContext(_deserializerFactory, _parser);
    }

    /**
     * Concrete implementation of DeserializationContext for testing purposes.
     */
    private static class TestDeserializationContext extends DeserializationContext {
        private final JsonParser parser;

        protected TestDeserializationContext(DeserializerFactory df, JsonParser p) {
            super(df);
            this.parser = p;
        }

        @Override
        public JsonParser getParser() {
            return parser;
        }

        // We need to inject the parser into the context because the method uses _parser field.
        // Since _parser is likely a private field in the real class, we rely on the fact 
        // that the method is part of the class and we are testing its logic.
        // In a real scenario, we might need to use Reflection to set the protected _parser field.
    }

    // Using Reflection to set the private field _parser in the context if necessary, 
    // but here we assume the context is set up via the constructor or provided by the environment.
    // Since the method uses `_parser`, we must ensure it's not null to avoid NPE in InvalidDefinitionException.from.

    @Test
    public void testInstantiationException_WithNullCause() {
        Class<?> targetClass = String.class;

        // Use reflection to inject the mock parser into the context instance
        injectParser(_context, _parser);

        JsonMappingException exception = _context.instantiationException(targetClass, null);

        assertNotNull(exception);
        assertTrue(exception instanceof InvalidDefinitionException);
        // If cause is null, msg should contain "problem: N/A"
        assertTrue(exception.getMessage().contains("problem: N/A"));
        assertTrue(exception.getMessage().contains("java.lang.String"));
    }

    @Test
    public void testInstantiationException_WithCauseAndMessage() {
        Class<?> targetClass = Integer.class;
        Throwable cause = new RuntimeException("Specific Error Message");

        injectParser(_context, _parser);

        JsonMappingException exception = _context.instantiationException(targetClass, cause);

        assertNotNull(exception);
        assertTrue(exception.getMessage().contains("problem: Specific Error Message"));
        assertEquals(cause, exception.getCause());
    }

    @Test
    public void testInstantiationException_WithCauseAndNullMessage() {
        Class<?> targetClass = Double.class;
        // A Throwable that returns null for getMessage()
        Throwable cause = new Throwable(null);

        injectParser(_context, _parser);

        JsonMappingException exception = _context.instantiationException(targetClass, cause);

        assertNotNull(exception);
        // If message is null, it should use ClassUtil.nameOf(cause.getClass())
        // which for Throwable is "java.lang.Throwable"
        assertTrue(exception.getMessage().contains("problem: java.lang.Throwable"));
        assertEquals(cause, exception.getCause());
    }

    /**
     * Helper method to inject the private _parser field into DeserializationContext via reflection.
     */
    private void injectParser(DeserializationContext context, JsonParser parser) {
        try {
            java.lang.reflect.Field field = DeserializationContext.class.getDeclaredField("_parser");
            field.setAccessible(true);
            field.set(context, parser);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}
